package com.otterview.agentsessionbridge;
import org.json.*;
import java.nio.*;import java.nio.charset.*;import java.security.*;import java.security.cert.*;import java.security.interfaces.ECPublicKey;import java.security.spec.*;import java.time.Instant;import java.util.*;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;
/** Exact-byte v2 admission/offer binding. No secret or derived key is a public field. */
final class ConnectorRtcCrypto {
 // A bounded clock difference may make a host's 60-second signed offer
 // appear slightly further in the future. Never extend local handshake time.
 static final long HANDSHAKE_MAX_MS=60_000;
 static final long OFFER_CLOCK_SKEW_MS=2_000;
 static long handshakeDeadline(JSONObject offer,long observedNow)throws Exception{return Math.min(Instant.parse(offer.getString("expiresAt")).toEpochMilli(),observedNow+HANDSHAKE_MAX_MS);}
 static String hex(byte[] bytes){StringBuilder out=new StringBuilder();for(byte b:bytes)out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}
 static byte[] utf8(String text)throws Exception{ByteBuffer encoded=StandardCharsets.UTF_8.newEncoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).encode(CharBuffer.wrap(text));byte[] bytes=new byte[encoded.remaining()];encoded.get(bytes);return bytes;}
 static byte[] hash(String text)throws Exception{return MessageDigest.getInstance("SHA-256").digest(utf8(text));}
 static String nonce(){byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);return hex(bytes);}
 static String hmac(byte[] key,String text)throws Exception{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(key,"HmacSHA256"));return hex(mac.doFinal(utf8(text)));}
 static String helloProof(byte[] key,String room,String nonce,String type,String device)throws Exception{return hmac(key,"agentbridge-webrtc-client-v2\n"+room+"\n"+nonce+"\n"+type+"\n"+device);}
 static String answerProof(byte[] key,String room,String connection,String client,String server,String statement,String sdp)throws Exception{return hmac(key,"agentbridge-webrtc-answer-v2\n"+room+"\n"+connection+"\n"+client+"\n"+server+"\n"+hex(hash(statement))+"\n"+hex(hash(sdp)));}
 static void exact(JSONObject value,String...fields)throws Exception{Set<String> allowed=new HashSet<>(Arrays.asList(fields));Iterator<String> keys=value.keys();int count=0;while(keys.hasNext()){if(!allowed.contains(keys.next()))throw new IllegalArgumentException("Unknown signed field");count++;}if(count!=allowed.size())throw new IllegalArgumentException("Missing signed field");}
 static String string(JSONObject value,String field,int bound)throws Exception{Object raw=value.get(field);if(!(raw instanceof String)||((String)raw).length()>bound)throw new IllegalArgumentException("Invalid signed string");return(String)raw;}
 static JSONObject verifyOffer(String statement,String pem,String signature,String pin,String room,String connection,String client,String authType,String device,long now)throws Exception{
  if(utf8(statement).length>128*1024||pem.length()>8192||signature.length()>256)throw new IllegalArgumentException("Offer bound");ConnectorStrictJson.validate(statement);JSONObject offer=new JSONObject(statement);
  exact(offer,"purpose","version","room","connectionId","clientNonce","serverNonce","authType","deviceId","sdp","iceServers","expiresAt");
  if(!"agentbridge-webrtc-offer-v2".equals(string(offer,"purpose",64))||!(offer.get("version") instanceof Integer)||offer.getInt("version")!=2)throw new IllegalArgumentException("Offer purpose");
  if(!room.equals(string(offer,"room",128))||!connection.equals(string(offer,"connectionId",128))||!client.equals(string(offer,"clientNonce",64))||!authType.equals(string(offer,"authType",8))||!device.equals(string(offer,"deviceId",128))||!string(offer,"serverNonce",64).matches("[0-9a-f]{64}"))throw new IllegalArgumentException("Offer identity binding");
  String expires=string(offer,"expiresAt",32);if(!expires.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z"))throw new IllegalArgumentException("Offer expiry");long until=Instant.parse(expires).toEpochMilli();if(until<=now||until-now>HANDSHAKE_MAX_MS+OFFER_CLOCK_SKEW_MS)throw new IllegalArgumentException("Offer expired");
  X509Certificate cert=(X509Certificate)CertificateFactory.getInstance("X.509").generateCertificate(new java.io.ByteArrayInputStream(utf8(pem)));cert.checkValidity(new Date(now));if(!MessageDigest.isEqual(ConnectorPolicy.digest(cert).getBytes(StandardCharsets.US_ASCII),pin.getBytes(StandardCharsets.US_ASCII)))throw new CertificateException("Computer identity pin");
  if(!(cert.getPublicKey() instanceof ECPublicKey))throw new CertificateException("Computer key type");AlgorithmParameters named=AlgorithmParameters.getInstance("EC");named.init(new ECGenParameterSpec("secp256r1"));ECParameterSpec wanted=named.getParameterSpec(ECParameterSpec.class),actual=((ECPublicKey)cert.getPublicKey()).getParams();if(!actual.getCurve().equals(wanted.getCurve())||!actual.getGenerator().equals(wanted.getGenerator())||!actual.getOrder().equals(wanted.getOrder())||actual.getCofactor()!=wanted.getCofactor())throw new CertificateException("Computer key curve");
  if(!signature.matches("[A-Za-z0-9+/]+={0,2}"))throw new SignatureException("Signature encoding");byte[] sig=android.util.Base64.decode(signature,android.util.Base64.NO_WRAP);if(!android.util.Base64.encodeToString(sig,android.util.Base64.NO_WRAP).equals(signature))throw new SignatureException("Noncanonical signature");Signature verifier=Signature.getInstance("SHA256withECDSA");verifier.initVerify(cert.getPublicKey());verifier.update(utf8(statement));if(!verifier.verify(sig))throw new SignatureException("Offer signature");
  String sdp=string(offer,"sdp",65536);if(!sdp.contains("m=application ")||java.util.regex.Pattern.compile("(?m)^m=(audio|video) ").matcher(sdp).find())throw new IllegalArgumentException("Only data channels allowed");
  Object raw=offer.get("iceServers");if(!(raw instanceof JSONArray))throw new IllegalArgumentException("ICE configuration");JSONArray servers=(JSONArray)raw;if(servers.length()>8)throw new IllegalArgumentException("ICE bound");for(int i=0;i<servers.length();i++){JSONObject server=servers.getJSONObject(i);exact(server,"urls","username","credential");string(server,"username",512);string(server,"credential",512);JSONArray urls=server.getJSONArray("urls");if(urls.length()<1||urls.length()>4)throw new IllegalArgumentException("ICE URL bound");for(int j=0;j<urls.length();j++){Object url=urls.get(j);if(!(url instanceof String)||((String)url).length()>512||!((String)url).matches("(?:stun|stuns|turn|turns):[^\\r\\n\\u0000]+"))throw new IllegalArgumentException("ICE URL");}}
  return offer;
 }
}
